# Extra panels are based on newly computed QC261 tables, not old artwork.
participant_overrides<-list()
short_group<-function(x)fcase(x==G3[1],'HC',x==G3[2],'AD',x==G3[3],'Other',default=as.character(x))
trilab<-function(p)scale_x_discrete(labels=setNames(c('HC','AD','Other'),G3))

# Give all representative feature plots the three predeclared comparisons.
for(jj in 1:3)local({j<-jj;id<-paste0('Fig4A',j);d<-source_tables[[id]]$data;st<-source_tables[[id]]$statistics;gene<-top$gene_name[j];oldcap<-captions[[id]]
 register(id,d,st,function(){p<-box(d,'signal',group='pathology_group',title=gene);dy<-diff(range(d$signal));h<-max(d$signal)+dy*.1;for(k in seq_len(nrow(st))){xx<-switch(st$contrast[k],Positive_vs_HC=c(1,2),Negative_vs_HC=c(1,3),Positive_vs_Negative=c(2,3));p<-p+annotate('segment',x=xx[1],xend=xx[2],y=h+(k-1)*dy*.21,yend=h+(k-1)*dy*.21,linewidth=LWD)+annotate('text',x=mean(xx),y=h+(k-1)*dy*.21+dy*.06,label=paste0('P=',fmtp(st$P[k])),family='Arial',size=FS/ggplot2::.pt)};p+labs(y='log2(1 + EXON SSB_LPKM)')},paste0(oldcap$en,' Bracket P values are nominal, two-sided adjusted limma contrasts; they are not unadjusted boxplot tests.'),paste0(oldcap$zh,' 括号P来自预定义双侧调整后limma对比，不是未调整箱图检验。'))
})
d<-source_tables$Fig4E$data;st<-clinical[task=='source'&population=='Disease-source'&trait=='mmse_observed_min'];register('Fig4E',d,st,function(){ss<-copy(st);ss[,label:=sprintf('n=%d; rho=%.2f\nP=%s',n,rho,fmtp(P))];ggplot(d,aes(mmse_observed_min,probability))+geom_point(colour='#3C5488',size=1.1,alpha=.7)+geom_text(data=ss,aes(x=Inf,y=Inf,label=label),inherit.aes=FALSE,hjust=1.05,vjust=1.1,family='Arial',size=FS/ggplot2::.pt)+facet_wrap(~region,nrow=2)+labs(x='Concurrent observed MMSE',y='Mean held-out source probability')+theme_pub()},'Held-out source probabilities and concurrent observed MMSE in AD plus Other (100 observed participants). Each region is an independently trained model. Facets report observed-pair n, two-sided Spearman rho and nominal P; covariate-adjusted associations and family-adjusted P accompany the data. This association is not independent clinical validation.','AD与Other合并人群100例实测同期MMSE与来源模型折外概率。四区域独立建模；每格显示配对n、双侧Spearman rho和原始P。调整后关联及全族校正P在源表，不能视为独立临床验证。')

# Four-region raw Ri with all three groups; P-values are descriptive Wilcoxon
# pair comparisons. Adjusted three-group coefficients remain a separate panel.
tri<-rd(path('results/regional_three_group_descriptive_tests.tsv'))
for(s in SPACES)local({space<-s;id<-paste0('FigS14',LETTERS[match(space,SPACES)]);d<-ri[region==space];st<-tri[region==space];register(id,d[,.(sample_id,pathology_group,Ri)],st,function(){p<-box(d,'Ri',group='pathology_group',title=space);span<-diff(range(d$Ri));h<-max(d$Ri)+span*.12;for(k in seq_len(nrow(st))){xx<-switch(st$contrast[k],Positive_vs_HC=c(1,2),Negative_vs_HC=c(1,3),Positive_vs_Negative=c(2,3));p<-p+annotate('segment',x=xx[1],xend=xx[2],y=h+(k-1)*span*.18,yend=h+(k-1)*span*.18,linewidth=LWD)+annotate('text',x=mean(xx),y=h+(k-1)*span*.18+span*.06,label=paste0('P=',fmtp(st$P[k])),family='Arial',size=FS/ggplot2::.pt)};p+labs(y='Ri (fixed GENE denominator)')},'All-participant three-group regional Ri. HC 144, AD 89, Other 28. Brackets are two-sided descriptive Wilcoxon P; the 12-test correction family and adjusted regression coefficients are supplied. The denominator is the same full-cohort mean GENE count for every region and contrast.','全参与者三组区域Ri：HC144、AD89、Other28。括号为双侧描述性Wilcoxon原始P，12检验族校正及调整后模型另附。所有区域和比较使用固定全队列GENE总计数均值分母。')})
supp_layout$S14<-paste0('FigS14',LETTERS[1:5])

# Whole-gene sensitivity evidence is named as such throughout.
for(k in seq_along(SPACES))local({j<-k;space<-SPACES[j];d<-rd(path('results',paste0(space,'_shared_unique.tsv')));st<-data.table(region=space,shared=sum(d$shared),positive_only=sum(d$positive_only),negative_only=sum(d$negative_only),direct=sum(d$direct_associated));z<-melt(st,id.vars='region');id<-paste0('FigS15',LETTERS[j]);register(id,z,st,function()ggplot(z,aes(variable,value,fill=variable))+geom_col(width=.65)+geom_text(aes(label=value),vjust=-.3,family='Arial',size=FS/ggplot2::.pt)+scale_fill_manual(values=c(shared='#3C5488',positive_only='#8064A2',negative_only='#E69F00',direct='#8A8A8A'))+scale_x_discrete(labels=c(shared='Shared',positive_only='AD vs HC\nonly',negative_only='Other vs HC\nonly',direct='AD vs Other'))+labs(x=NULL,y='Associated features',title=space)+theme_pub()+theme(legend.position='none'),'Shared and threshold-specific associations for each region. A significant result in one group and not another does not establish a group difference; the direct AD-versus-Other comparison supplies that test.','各区域共享及阈值特有集合；一组显著、另一组不显著不等于组间差异，组间差异由AD对Other直接检验。');participant_overrides[[id]]<<-m[complete_primary==TRUE,.(sample_id)]})
supp_layout$S15<-paste0('FigS15',LETTERS[1:4])

trait_labels<-c(trait_labels,rbc_10e12_l='RBC',hematocrit_pct='Hematocrit',mcv_fl='MCV',cholesterol_mmol_l='Total cholesterol',triglycerides_mmol_l='Triglycerides',ldl_c_mmol_l='LDL cholesterol',serum_abeta42_pg_ml='Serum Aβ42',serum_tau181_pg_ml='Serum tau181',age_at_onset_years='Age at onset')
labheat<-function(d,fill='rho',cols='region',title=NULL){x<-copy(d);x[,display:=ifelse(trait%in%names(trait_labels),unname(trait_labels[trait]),trait)];ggplot(x,aes(.data[[cols]],display,fill=.data[[fill]]))+geom_tile(colour='white')+geom_text(aes(label=paste0('n=',n,'\nP=',fmtp(P))),family='Arial',size=FS/ggplot2::.pt)+scale_fill_gradient2(low='#0072B2',mid='white',high='#D55E00',midpoint=0,limits=c(-1,1))+labs(x=NULL,y=NULL,fill='Spearman rho',title=title)+theme_pub()}
sigclin<-rd(path('results/clinical/regional_signal_trait_associations.tsv'))
for(k in 1:4)local({j<-k;metric_value<-if(j<=2)'Ri'else'mean_log_signal';family_value<-if(j%%2==1)c('wbc_10e9_l','neutrophil_pct','lymphocyte_pct','monocyte_pct','hemoglobin_g_l','platelet_10e9_l')else c('glucose_mmol_l','creatinine_umol_l','cholesterol_mmol_l','hdl_c_mmol_l','ldl_c_mmol_l','triglycerides_mmol_l');d<-sigclin[population=='Disease-source'&metric==metric_value&trait%in%family_value];id<-paste0('FigS16',LETTERS[j]);register(id,d,d,function()labheat(d,title=paste(metric_value,if(j%%2==1)'blood count'else'chemistry')),'Disease-group observed clinical pairs versus regional Ri or mean log signal. Cells report actual n and nominal Spearman P; full adjusted associations and multiplicity correction are provided. No imputed observations are used.','疾病人群区域Ri/平均log信号与血常规/生化实测配对关联。每格显示实际n及Spearman原始P；调整后关联和全族校正在源表，不使用插补值。');participant_overrides[[id]]<<-rbindlist(lapply(seq_len(nrow(d)),function(i){pa<-rd(path('results/clinical/participants',paste0('signal_Disease_source_',d$region[i],'_',metric_value,'_',d$trait[i],'.tsv')));pa[,`:=`(region=d$region[i],trait=d$trait[i])];pa}))})
supp_layout$S16<-paste0('FigS16',LETTERS[1:4])

repclin<-rd(path('results/clinical/representative_feature_trait_associations.tsv'))
for(k in 1:2)local({j<-k;family_value<-if(j==1)c('mmse_observed_min','moca_unambiguous_score','adl_unambiguous_score')else c('wbc_10e9_l','glucose_mmol_l','creatinine_umol_l','hdl_c_mmol_l');d<-repclin[population=='Disease-source'&trait%in%family_value];id<-paste0('FigS17',LETTERS[j]);register(id,d,d,function()labheat(d,cols='gene_name',title='Representative EXON features'),'Concurrent clinical associations for the three cohort-selected EXON features. Cells show actual observed-pair n and nominal P; whole predefined-family adjusted results are supplied. Cohort-derived feature selection prevents treating these as an independent validation.','三个队列内筛选的代表EXON特征与同期临床指标关联。每格为实测配对n和原始P，完整预定检验族校正另附。队列内筛选不能作为独立验证。');participant_overrides[[id]]<<-rbindlist(lapply(seq_len(nrow(d)),function(i){pa<-rd(path('results/clinical/participants',paste0('representative_Disease_source_',d$gene_id[i],'_',d$trait[i],'.tsv')));pa[,`:=`(gene_id=d$gene_id[i],trait=d$trait[i])];pa}))})
supp_layout$S17<-c('FigS17A','FigS17B')

for(k in 1:2)local({j<-k;pop<-if(j==1)'Disease-source'else G3[2];d<-clinical[task=='pathology'&population==pop&trait%in%c('mmse_observed_min','moca_unambiguous_score','adl_unambiguous_score','wbc_10e9_l','glucose_mmol_l')];id<-paste0('FigS18',LETTERS[j]);register(id,d,d,function()labheat(d,title=if(j==1)'AD–Other model: disease groups'else'AD–Other model: AD subgroup'),'Pathology-model held-out score associations with observed clinical measures, with actual n and nominal P. Adjusted and family-corrected results accompany each panel.','病理模型折外评分与实测临床指标关联，显示实际n和原始P；调整及全族校正随图交付。');participant_overrides[[id]]<<-rbindlist(lapply(seq_len(nrow(d)),function(i){pa<-rd(path('results/clinical/participants',paste0('pathology_',gsub('[^A-Za-z0-9]','_',d$population[i]),'_',d$region[i],'_',d$trait[i],'.tsv')));pa[,`:=`(region=d$region[i],trait=d$trait[i])];pa}))})
supp_layout$S18<-c('FigS18A','FigS18B')

# Each annotation space gets a dedicated, aligned 2×2 age-stratified page.
for(si in seq_along(SPACES)){
 space_value<-SPACES[si];sets<-list();pids<-character()
 for(bi in 1:3)local({space<-space_value;j<-bi;md<-c('A_age_5059','A_age_6069','A_age_70')[j];d<-rd(path('results/differential',paste0(space,'__',md,'__Disease_vs_HC.tsv')));id<-paste0('FigS',18+si,LETTERS[j]);st<-d;register(id,d,st,function()volcano(d,paste(space,c('50–59 years','60–69 years','≥70 years')[j])),'Within-age-band disease-group versus HC associations, adjusting continuous age, sex and technical covariates. Feature colors use within-space/contrast BH correction; actual model n is in the supplied participant list.','年龄分层内疾病组对HC关联，继续调整实际年龄、性别和技术变量；颜色依各区域/对比BH校正，实际模型人数在名单。');participant_overrides[[id]]<<-rd(path('results/differential',paste0(space,'__',md,'__participants.tsv')))} )
 for(md in c('A_age_5059','A_age_6069','A_age_70')){a<-rd(path('results/differential',paste0(space_value,'__',md,'__Disease_vs_HC.tsv')));sets[[md]]<-a[FDR<.05,gene_id]}
 local({space<-space_value;j<-si;union_ids<-sort(unique(unlist(sets)));up<-data.table(gene_id=union_ids);for(n in names(sets))up[,(n):=gene_id%in%sets[[n]]];if(nrow(up)){up[,pattern:=paste0(as.integer(A_age_5059),as.integer(A_age_6069),as.integer(A_age_70))];d<-up[,.N,by=pattern]}else d<-data.table(pattern='No age-band associations',N=0L);id<-paste0('FigS',18+j,'D');register(id,d,up,function()ggplot(d,aes(pattern,N))+geom_col(fill='#3C5488')+geom_text(aes(label=N),vjust=-.3,family='Arial',size=FS/ggplot2::.pt)+labs(x='Membership: 50–59 / 60–69 / ≥70',y='Associated features',title=paste(space,'exact age-band intersections'))+theme_pub(),'Exact age-band membership counts; 1 means passing the prespecified within-band BH threshold. This displays overlap, not a test of interaction or age independence.','三个年龄层严格显著集合的成员交集，1表示该年龄层达到预定BH阈值；交集不是交互或年龄独立检验。');participant_overrides[[id]]<<-m[complete_primary==TRUE&age_years>=50,.(sample_id)]})
 supp_layout[[paste0('S',18+si)]]<-paste0('FigS',18+si,LETTERS[1:4])
}

# Display only a prespecified top-12 subset; export all significant rows in the
# workbook and keep the unscaled values and per-gene Z-scores separately.
z<-readRDS(path('matrices/EXON_inputs.rds'));aa<-rd(path('results/differential/EXON__A_primary__Disease_vs_HC.tsv'))[FDR<.05][order(FDR,-abs(beta),gene_id)][1:12];Y<-log2(1+z$lpkm[match(aa$gene_id,z$annotation$gene_id),m$sample_id,drop=FALSE]);mm<-m[order(factor(pathology_group,levels=G3),age_years,sample_id)];YS<-Y[,match(mm$sample_id,m$sample_id)];zs<-t(scale(t(YS)));rownames(zs)<-aa$gene_name;d<-as.data.table(as.table(zs));setnames(d,c('gene_name','sample_id','zscore'));d[,sample_id:=as.character(sample_id)];d[,sample_order:=match(sample_id,mm$sample_id)];d<-merge(d,mm[,.(sample_id,pathology_group)],by='sample_id');st<-aa;register('FigS23A',d,st,function()ggplot(d,aes(sample_order,factor(gene_name,levels=rev(aa$gene_name)),fill=pmax(-3,pmin(3,zscore))))+geom_tile()+scale_fill_gradient2(low='#0072B2',mid='white',high='#D55E00',limits=c(-3,3))+labs(x='Participants ordered: HC | AD | Other',y=NULL,fill='Within-feature Z')+theme_pub()+theme(axis.text.x=element_blank(),axis.ticks.x=element_blank()),'Twelve ranked primary EXON associations, displaying within-feature Z-scores clipped at ±3 for color only. Ranking used corrected P, absolute effect and gene ID. Participants are grouped HC, AD, Other and ordered by age then ID. Full unscaled data are supplied; this cohort-selected display is not a classifier validation.','主EXON关联前12名的特征内Z-score热图，颜色截断±3。排序依校正P、效应绝对值及基因ID，样本依HC/AD/Other、年龄、ID排列。原尺度值另附；队列内筛选展示不属于分类验证。');participant_overrides$FigS23A<-m[,.(sample_id)]
savebook(list(Counts=z$counts[match(aa$gene_id,z$annotation$gene_id),m$sample_id],Log_signal=YS,Z_scores=zs,Selected_features=aa,Participants=mm[,.(sample_id,pathology_group,age_years)]),path('tables/Primary_EXON_heatmap_source.xlsx'))
supp_layout$S23<-c('FigS23A')
rm(z,Y,YS,zs)

# Final-size visual QA revision: full-width exposure curve is supplementary;
# main Figure 3 retains the main profile, length robustness and a 2×2 functional
# context block. Renumber the actual files and their data together, not just tags.
oldids<-paste0('Fig3',LETTERS[2:7]);newids<-c('FigS24A','Fig3B','Fig3C','Fig3D','Fig3E','Fig3F')
rf<-registry[oldids];sf<-source_tables[oldids];cf<-captions[oldids]
registry[oldids]<-NULL;source_tables[oldids]<-NULL;captions[oldids]<-NULL
for(k in seq_along(oldids)){registry[[newids[k]]]<-rf[[k]];source_tables[[newids[k]]]<-sf[[k]];captions[[newids[k]]]<-cf[[k]]}
supp_layout$S24<-c('FigS24A')
participant_overrides$FigS24A<-m[,.(sample_id)];participant_overrides$Fig3B<-m[complete_primary==TRUE,.(sample_id)]
for(id in paste0('Fig3',LETTERS[3:6]))participant_overrides[[id]]<-m[complete_primary==TRUE,.(sample_id)]
captions$FigS24A$en<-gsub('disease-source 150','AD plus Other 117',captions$FigS24A$en,fixed=TRUE)
# Custom enrichment display fits 8.5-pt labels at 183-mm composite width. Full
# ontology terms remain exact in source data; only word wrapping changes.
for(k in 1:4)local({j<-k;cat_value<-c('Process','Component','RCTM','HPO')[j];id<-paste0('Fig3',LETTERS[j+2]);d<-ptop[set=='All'&category==cat_value];oldcap<-captions[[id]];title<-c(Process='GO biological process',Component='GO cellular component',RCTM='Reactome',HPO='HPO')[[cat_value]];register(id,d,d,function(){xx<-copy(d);xx[,term_label:=stringr::str_wrap(description,26)];ggplot(xx,aes(-log10(pmax(p_value,.Machine$double.xmin)),reorder(term_label,-fdr),size=number_of_genes))+geom_point(colour='#3C5488')+scale_size_continuous(range=c(1.6,3.8))+labs(x=expression(-log[10](P)),y=NULL,title=title)+theme_pub()+theme(legend.position='none',axis.text.y=element_text(lineheight=.85),plot.margin=margin(3,5,3,3))},oldcap$en,oldcap$zh)})
for(id in names(registry))local({ii<-id;original_fn<-registry[[ii]];registry[[ii]]<<-function(){p<-original_fn();if(ii%in%paste0('Fig1',LETTERS[2:5]))p<-p+labs(y='SSB Ri')+scale_x_discrete(labels=c(HC='HC\nn = 144','Disease-source'='AD + Other\nn = 117'));if(ii=='Fig2F')p<-p+scale_x_discrete(labels=c(Positive_vs_HC='AD/HC',Negative_vs_HC='Other/HC',Positive_vs_Negative='AD/Other'))+theme(legend.position='none',axis.text.x=element_text(angle=30,hjust=1));if(ii=='Fig2G')p<-p+labs(x='AD vs HC effect',y='Other vs HC effect');if(grepl('^Fig4A',ii))p<-p+labs(y='EXON log SSB signal');if(ii=='Fig4D2')p<-p+labs(y='Repeat AUC');if(ii=='Fig4F')p<-p+labs(subtitle='Adjusted MMSE (n=100)');if(ii=='Fig4E')p<-p+labs(y='Held-out source probability')+scale_y_continuous(limits=c(0,1.4),breaks=c(0,.5,1));p}})
source('code/08b_figure1_three_groups.R',local=TRUE)
source('code/08c_visual_QA_revision.R',local=TRUE)
